select is((select count(*)::integer from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in('restitch_selection_roots','restitch_selection_slots','restitch_selection_candidates') and c.relrowsecurity and c.relforcerowsecurity),3,'all storage tables enforce row security');
select ok(not has_function_privilege('authenticated','public.service_cas_restitch_selection_slot(uuid,uuid,uuid,text,jsonb,jsonb)','execute') and not has_function_privilege('anon','public.service_settle_restitch_selection_range(uuid,uuid,uuid,text,uuid,jsonb,jsonb)','execute'),'browser roles cannot reserve or settle');
select ok(has_function_privilege('service_role','public.service_cas_restitch_selection_slot(uuid,uuid,uuid,text,jsonb,jsonb)','execute'),'service owns CAS');
select ok(has_table_privilege('wishly_analytics_ro','public.analytics_restitch_selection_slots','select'),'diagnostic role sees only the projection');
select ok(not has_table_privilege('service_role','private.restitch_selection_roots','select,insert,update,delete'),'service has no direct storage access');
select is((select count(*)::integer from private.restitch_selection_slots where root_operation_id='b1550000-0000-4000-8000-000000000051'),2,'one initial slot per side');
select throws_ok('update private.restitch_selection_roots set recipe=recipe||''{"changed":true}''::jsonb where root_operation_id=''b1550000-0000-4000-8000-000000000051''','55000','WRONG_STATE','accepted root never changes');
select is(public.service_read_restitch_selection_slot('b1550000-0000-4000-8000-000000000051','b1550000-0000-4000-8000-000000000011','b1550000-0000-4000-8000-000000000001','end'),null::jsonb,'foreign actor cannot read root');
select throws_ok('select public.service_cas_restitch_selection_slot(''b1550000-0000-4000-8000-000000000051'',''b1550000-0000-4000-8000-000000000011'',''b1550000-0000-4000-8000-000000000002'',''start'',(select budget from selection_vectors where name=''empty''),(select budget from selection_vectors where name=''selected''))','55000','RESTITCH_SOURCES_INVALID','disabled slot does not select');
select ok(public.service_cas_restitch_selection_slot('b1550000-0000-4000-8000-000000000051','b1550000-0000-4000-8000-000000000011','b1550000-0000-4000-8000-000000000002','end',(select budget from selection_vectors where name='empty'),(select budget from selection_vectors where name='selected')),'selection matches shared kernel');

